import {
  Mesh,
  PlaneGeometry,
  Group,
  MeshStandardNodeMaterial,
  PointLight
} from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // --- STAGE BACKDROP (Engineered Gradient) ---
  const backdropGeo = new PlaneGeometry(7.0, 3.5);
  const backdropMat = new MeshStandardNodeMaterial();

  // TSL Vertical Gradient construction
  const colorTop = vec3(
    parseInt(colors.surface.slice(1, 3), 16) / 255,
    parseInt(colors.surface.slice(3, 5), 16) / 255,
    parseInt(colors.surface.slice(5, 7), 16) / 255
  );
  const colorBottom = vec3(
    parseInt(colors.ink.slice(1, 3), 16) / 255,
    parseInt(colors.ink.slice(3, 5), 16) / 255,
    parseInt(colors.ink.slice(5, 7), 16) / 255
  );

  backdropMat.colorNode = mix(colorBottom, colorTop, uv().y);
  backdropMat.roughness = 0.6;
  backdropMat.metalness = 0.2;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.15;
  group.add(backdrop);

  // --- HERO TEXTURED PLANE ---
  const imageGeo = new PlaneGeometry(4.0, 2.5);
  const imageMat = new MeshStandardNodeMaterial({
    transparent: true,
    opacity: 0.85,
    roughness: 0.4,
    metalness: 0.1
  });

  const imageMesh = new Mesh(imageGeo, imageMat);
  imageMesh.position.z = -0.05;
  group.add(imageMesh);

  // Load Image Asset via async queue, non-blocking
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((texture) => {
        imageMat.map = texture;
        imageMat.needsUpdate = true;
      })
      .catch((err) => console.warn('Failed to load Collection image texture', err));
  }

  // --- TYPOGRAPHY (Collection Title) ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const titleItem = items.find(item => item.role === 'headline') ?? { text: 'Collection' };

  // Translate 96px target to roughly 0.45 scene units
  const titleText = ctx.fontAtlas.createText(titleItem.text, {
    fontSize: 0.45,
    color: colors.paper,
    align: 'center'
  });
  titleText.position.set(0, 0, 0.1);
  group.add(titleText);

  // --- ACCENT LIGHTING ---
  const accentLight = new PointLight(colors.accent, 1.2, 8.0);
  accentLight.position.set(0, 1.2, 1.5);
  group.add(accentLight);

  // --- ENTRANCE ANIMATION ---
  const tl = gsap.timeline();
  tl.fromTo(titleText.position, 
    { z: -0.2 }, 
    { z: 0.1, duration: 1.2, ease: 'power4.out' }
  );
  tl.fromTo(imageMesh.scale,
    { x: 0.9, y: 0.9 },
    { x: 1, y: 1, duration: 1.4, ease: 'power3.out' },
    '<0.1'
  );

  // --- CLEANUP ---
  group.userData = {
    cleanup() {
      tl.kill();
      backdropGeo.dispose();
      backdropMat.dispose();
      imageGeo.dispose();
      imageMat.dispose();
    }
  };

  return group;
}
